/**
 * 「四格 pastel 手绘贴纸场景」——设计稿中的位图贴纸，用同色系 SVG 手绘风重绘。
 * 用于首页主视觉卡、日历事件卡与事件详情页顶部。
 */
export function StickerScene({ className }: ArtProps) {
  return (
    <svg viewBox="0 0 127 127" className={className} aria-hidden="true">
      {/* 贴纸底板 */}
      <rect width="127" height="127" fill="url(#pattern0_101_733)"/>
      <defs>
      <pattern id="pattern0_101_733" patternContentUnits="objectBoundingBox" width="1" height="1">
      <use href="#image0_101_733" transform="scale(0.00787402)"/>
      </pattern>
      <image id="image0_101_733" width="127" height="127" preserveAspectRatio="none" href="data:image/png;base64,"/>
      </defs>
    </svg>
	
  )
}

